import RNA
import random
import sys
from multiprocessing import Pool

target = "...((((((....))))))(((((....)))))((((((....))))))(((((....)))))((((((....))))))(((((....)))))(((((....)))))((((((....)))))).(((((....)))))((((((....))))))(((((....)))))((((((....))))))(((((....)))))((((((....))))))"

def pairs_from_db(db):
    stack=[]; pairs=set()
    for i,c in enumerate(db):
        if c=='(': stack.append(i)
        elif c==')':
            j=stack.pop(); pairs.add((j,i))
    return pairs

target_pairs = pairs_from_db(target)
n = len(target)
unpaired = [i for i in range(n) if target[i]=='.']
paired = sorted(target_pairs)

def random_seq(rng):
    s=['A']*n
    for (i,j) in paired:
        r = rng.choice(['GC','CG','AU','UA'])
        s[i]=r[0]; s[j]=r[1]
    return ''.join(s)

def score(seq):
    fc = RNA.fold_compound(seq)
    ss, mfe = fc.mfe()
    p = pairs_from_db(ss)
    d = len(target_pairs ^ p)
    return d, ss

def mutate(seq, rng, k=1):
    s=list(seq)
    for _ in range(k):
        if rng.random()<0.5 and paired:
            i,j = rng.choice(paired)
            r = rng.choice(['GC','CG','AU','UA'])
            s[i]=r[0]; s[j]=r[1]
        else:
            i = rng.choice(unpaired)
            s[i]=rng.choice('ACGU')
    return ''.join(s)

def worker(seed):
    rng = random.Random(seed*131+7)
    seq = random_seq(rng)
    d,ss = score(seq)
    best=(d,seq)
    T=3.0
    for it in range(3000):
        cand = mutate(seq, rng, rng.choice([1,1,2]))
        d2,ss2 = score(cand)
        if d2 < d or rng.random() < 0.1*(T):
            seq=cand; d=d2
            if d < best[0]:
                best=(d,seq)
                if d==0: break
        T *= 0.9988
    return best

if __name__=='__main__':
    best=None
    with Pool(32) as p:
        for res in p.imap_unordered(worker, range(256), chunksize=1):
            if best is None or res[0]<best[0]:
                best=res
                sys.stdout.write(f"best d={res[0]}\n"); sys.stdout.flush()
            if best[0]==0: 
                p.terminate(); break
    sys.stdout.write(f"FINAL {best[0]}\n{best[1]}\n"); sys.stdout.flush()
EOF
cd /tmp && timeout 120 python3 /tmp/solve4.py > /tmp/out4.txt 2>&1; echo "EXIT $?"; tail -20 /tmp/out4.txt

